INSERT INTO `destinations` VALUES (1,2,'Hß╗ô Lß║»k','Lak Lake','ho-lak','Hß╗ô n╞░ß╗¢c ngß╗ìt tß╗▒ nhi├¬n lß╗¢n thß╗⌐ 2 Viß╗çt Nam, gß║»n vß╗¢i v─ân ho├í M\'n├┤ng.','The 2nd largest natural freshwater lake in Vietnam, deeply connected to M\'nong culture.','Hß╗ô Lß║»k l├á mß╗Öt trong nhß╗»ng hß╗ô n╞░ß╗¢c ngß╗ìt tß╗▒ nhi├¬n lß╗¢n nhß║Ñt Viß╗çt Nam, nß║▒m tß║íi huyß╗çn Lß║»k, tß╗ënh ─Éß║»k Lß║»k. Du kh├ích c├│ thß╗â ─æi thuyß╗ün ─æß╗Öc mß╗Öc, c╞░ß╗íi voi, tham quan Biß╗çt ─æiß╗çn Bß║úo ─Éß║íi v├á trß║úi nghiß╗çm v─ân ho├í ng╞░ß╗¥i M\'n├┤ng quanh hß╗ô.','Lak Lake is a famous eco-tourism destination in Dak Lak. Visitors can experience dugout canoe rides, admire the sunset on the lake, and explore the traditional longhouses of the M\'nong people.','Huyß╗çn Lß║»k, ─Éß║»k Lß║»k','https://nhanghitaynguyen.com/wp-content/uploads/2020/09/tham-quan-ho-lak.jpg',3.0,'low',5.0,12.420300,108.185400,'thi├¬n nhi├¬n,hß╗ô,v─ân ho├í,thuyß╗ün ─æß╗Öc mß╗Öc','2026-06-28 05:57:43'),(2,1,'Th├íc Dray Nur','Dray Nur Waterfall','thac-dray-nur','Mß╗Öt trong nhß╗»ng th├íc n╞░ß╗¢c h├╣ng v─⌐ nhß║Ñt T├óy Nguy├¬n.','One of the most majestic waterfalls in the Central Highlands.','Th├íc Dray Nur nß║▒m tr├¬n d├▓ng s├┤ng S├¬r├¬pß╗æk, l├á mß╗Öt trong nhß╗»ng th├íc n╞░ß╗¢c ─æß║╣p v├á h├╣ng v─⌐ nhß║Ñt khu vß╗▒c T├óy Nguy├¬n, th├¡ch hß╗úp cho trekking, chß╗Ñp ß║únh v├á tß║»m th├íc.','Dray Nur waterfall is breathtakingly beautiful with its massive curtain of water. You can explore the mysterious cave behind the waterfall and enjoy the pristine nature.','Huyß╗çn Kr├┤ng Ana, ─Éß║»k Lß║»k','https://trungnguyenhealing.com/resources/uploads/Dray%20-Nur.jpg',2.5,'low',4.7,12.566700,108.116700,'thi├¬n nhi├¬n,th├íc n╞░ß╗¢c,trekking','2026-06-28 05:57:43'),(3,1,'Th├íc Dray S├íp','Dray Sap Waterfall','thac-dray-sap','Th├íc \"n╞░ß╗¢c kh├│i\" nß╗òi tiß║┐ng gß║ºn Bu├┤n Ma Thuß╗Öt.','The famous \'smoke waterfall\' near Buon Ma Thuot.','Th├íc Dray S├íp (ngh─⌐a l├á \"th├íc kh├│i\") nß╗òi tiß║┐ng vß╗¢i d├▓ng n╞░ß╗¢c tung bß╗ìt trß║»ng nh╞░ s╞░╞íng kh├│i, gß║ºn khu vß╗▒c Dray Nur, thuß║¡n tiß╗çn kß║┐t hß╗úp tham quan trong c├╣ng ng├áy.','Located near Dray Nur, Dray Sap is known for the mist that rises from the falling water, creating a mystical atmosphere in the middle of the jungle.','Huyß╗çn Kr├┤ng Ana, ─Éß║»k Lß║»k','https://ticotravel.com.vn/wp-content/uploads/2022/10/Thac-Dray-Sap-5.jpg',2.0,'low',4.5,12.572800,108.108300,'thi├¬n nhi├¬n,th├íc n╞░ß╗¢c','2026-06-28 05:57:43'),(4,3,'Bu├┤n ─É├┤n','Buon Don','buon-don','L├áng v─ân ho├í nß╗òi tiß║┐ng vß╗¢i nghß╗ü s─ân bß║»t v├á thuß║ºn d╞░ß╗íng voi.','Famous for its elephant taming tradition and the suspension bridge over Serepok river.','Bu├┤n ─É├┤n l├á ─æiß╗âm ─æß║┐n v─ân ho├í nß╗òi tiß║┐ng cß╗ºa ─Éß║»k Lß║»k, n╞íi du kh├ích t├¼m hiß╗âu vß╗ü nghß╗ü thuß║ºn d╞░ß╗íng voi, tham quan nh├á d├ái truyß╗ün thß╗æng, cß║ºu treo v├á mß╗Ö vua voi Khunjunob.','Experience the wild nature, walk on the long suspension bridge, and learn about the unique culture of the local ethnic minorities.','Huyß╗çn Bu├┤n ─É├┤n, ─Éß║»k Lß║»k','https://ik.imagekit.io/tvlk/blog/2023/05/buon-don-1.jpg?tr=dpr-2,w-675',3.0,'medium',4.4,13.016700,107.833300,'v─ân ho├í,voi,nh├á d├ái,cß║ºu treo','2026-06-28 05:57:43'),(5,4,'V╞░ß╗¥n quß╗æc gia Yok ─É├┤n','Yok Don National Park','vuon-quoc-gia-yok-don','V╞░ß╗¥n quß╗æc gia lß╗¢n nhß║Ñt Viß╗çt Nam, n╞íi sinh sß╗æng cß╗ºa voi rß╗½ng.','The only national park in Vietnam that preserves the dipterocarp forest ecosystem.','Yok ─É├┤n l├á v╞░ß╗¥n quß╗æc gia lß╗¢n nhß║Ñt Viß╗çt Nam, nß╗òi bß║¡t vß╗¢i hß╗ç sinh th├íi rß╗½ng kh├┤ ─æß║╖c tr╞░ng T├óy Nguy├¬n v├á l├á n╞íi triß╗ân khai m├┤ h├¼nh du lß╗ïch th├ón thiß╗çn vß╗¢i voi (kh├┤ng c╞░ß╗íi voi).','A paradise for nature lovers. You can join trekking tours, go bird watching, and see the ethical elephant tours where elephants roam freely.','Huyß╗çn Bu├┤n ─É├┤n, ─Éß║»k Lß║»k','https://luhanhvietnam.com.vn/du-lich/vnt_upload/news/04_2020/vuon-quoc-gia-yok-don.jpg',4.0,'medium',4.5,13.083300,107.783300,'thi├¬n nhi├¬n,rß╗½ng,voi,sinh th├íi','2026-06-28 05:57:43'),(6,5,'C├á ph├¬ Bu├┤n Ma Thuß╗Öt','Buon Ma Thuot Coffee','ca-phe-buon-ma-thuot','Thß╗º phß╗º c├á ph├¬ Viß╗çt Nam, trß║úi nghiß╗çm v─ân ho├í c├á ph├¬ ─æß║╖c sß║»c.','The coffee capital of Vietnam, a great place to experience the culture of roasted coffee.','Bu├┤n Ma Thuß╗Öt ─æ╞░ß╗úc mß╗çnh danh l├á \"thß╗º phß╗º c├á ph├¬\" cß╗ºa Viß╗çt Nam. Du kh├ích c├│ thß╗â tham quan c├íc ─æß╗ôn ─æiß╗ün c├á ph├¬, Bß║úo t├áng Thß║┐ giß╗¢i C├á ph├¬ v├á th╞░ß╗ƒng thß╗⌐c c├á ph├¬ nguy├¬n chß║Ñt ─Éß║»k Lß║»k.','A must-visit for coffee lovers. You can learn about the history of coffee, admire unique architecture, and taste premium coffee blends.','TP. Bu├┤n Ma Thuß╗Öt, ─Éß║»k Lß║»k','https://th.bing.com/th/id/R.e44b2f35f39e2f95124b573a71df1395?rik=lad4Uf7u8%2fjhJQ&pid=ImgRaw&r=0',2.0,'free',4.6,12.666700,108.050000,'ß║⌐m thß╗▒c,c├á ph├¬,bß║úo t├áng','2026-06-28 05:57:43'),(7,3,'Bu├┤n Ak├┤ Dh├┤ng','Ako Dhong Village','buon-ako-dhong','Bu├┤n l├áng ├è ─É├¬ ─æß║╣p nhß║Ñt Bu├┤n Ma Thuß╗Öt.','A peaceful E De village in the heart of Buon Ma Thuot city.','Bu├┤n Ak├┤ Dh├┤ng nß║▒m ngay trong l├▓ng th├ánh phß╗æ Bu├┤n Ma Thuß╗Öt, nß╗òi tiß║┐ng vß╗¢i nhß╗»ng ng├┤i nh├á d├ái truyß╗ün thß╗æng cß╗ºa ng╞░ß╗¥i ├è ─É├¬ v├á kh├┤ng gian xanh y├¬n b├¼nh.','Ako Dhong is known for its beautiful traditional longhouses, peaceful atmosphere, and the rich cultural heritage of the E De people.','TP. Bu├┤n Ma Thuß╗Öt, ─Éß║»k Lß║»k','https://52hz.vn/wp-content/uploads/2021/12/1-buon-ako-dhong.jpg',1.5,'free',4.3,12.683300,108.033300,'v─ân ho├í,nh├á d├ái,├è ─É├¬','2026-06-28 05:57:43'),(8,2,'Hß╗ô Ea Kao','Ea Kao Lake','ho-ea-kao','Hß╗ô n╞░ß╗¢c rß╗Öng lß╗¢n gß║ºn trung t├óm th├ánh phß╗æ, th├¡ch hß╗úp cß║»m trß║íi.','A serene lake surrounded by green forests, perfect for picnics and sunset watching.','Hß╗ô Ea Kao l├á hß╗ô nh├ón tß║ío rß╗Öng lß╗¢n nß║▒m gß║ºn TP. Bu├┤n Ma Thuß╗Öt, kh├┤ng kh├¡ m├ít mß║╗, ph├╣ hß╗úp cho d├ú ngoß║íi, cß║»m trß║íi v├á chß╗Ñp ß║únh.','Ea Kao Lake is a great place to relax, enjoy the fresh air, and watch the beautiful sunset over the water.','TP. Bu├┤n Ma Thuß╗Öt, ─Éß║»k Lß║»k','https://static-cms-vovworld.zadn.vn/uploaded/buihangm/2022_03_24/6_rgdj.jpg',2.0,'free',4.2,12.616700,108.083300,'thi├¬n nhi├¬n,hß╗ô,cß║»m trß║íi','2026-06-28 05:57:43');
